"use client";

import { useCallback, useState, type ReactNode } from "react";
import { useQuery } from "@tanstack/react-query";
import { ArrowRight, ArrowUpRight, CalendarClock, Check, CircleHelp, Clock3, Coins, Download, ExternalLink, FileCheck2, Landmark, LockKeyhole, RefreshCw, Save, Settings2, ShieldCheck, Users, Wallet as WalletIcon } from "lucide-react";
import { formatUnits, isAddress, parseUnits, zeroAddress } from "viem";
import { ageLabel, getData, pollingInterval, shortAddress } from "@/lib/live-api";
import { CHAIN_ID, EXPLORER, USDG } from "@/lib/market-types";
import { WalletButton, type WalletState } from "./wallet";
