import "./token-rewards.css";

function rewardAmount(value: string | null | undefined, decimals = 18, places = 6) {
  if (value == null || !/^\d+$/.test(value)) return "—";
  const [whole, fraction = ""] = formatUnits(BigInt(value), decimals).split(".");
  const trimmed = fraction.slice(0, places).replace(/0+$/, "");
  if (whole === "0" && !trimmed && BigInt(value) > BigInt(0)) return `<${places ? `0.${"0".repeat(places - 1)}1` : "1"}`;
  return `${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}${trimmed ? `.${trimmed}` : ""}`;
}
function percent(bps: number) { return `${(bps / 100).toFixed(2).replace(/\.?0+$/, "")}%`; }
function duration(seconds: number) {
  if (seconds % 86400 === 0) return `${seconds / 86400} day${seconds === 86400 ? "" : "s"}`;
  if (seconds % 3600 === 0) return `${seconds / 3600} hour${seconds === 3600 ? "" : "s"}`;
  if (seconds % 60 === 0) return `${seconds / 60} minute${seconds === 60 ? "" : "s"}`;
  return `${seconds} seconds`;
}
function timestamp(value: string | number | null | undefined) {
  if (value == null) return "Awaiting first distribution";
  const date = typeof value === "number" ? new Date(value * 1000) : new Date(value);
  return Number.isFinite(date.getTime()) ? date.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "Awaiting source";
}
function Notice({ children, warning = false }: { children: ReactNode; warning?: boolean }) { return <div className={`rewards-notice ${warning ? "is-warning" : ""}`} role="status"><CircleHelp size={17}/><p>{children}</p></div>; }
function AddressLink({ address, label }: { address: string; label?: string }) { return <a href={`${EXPLORER}/address/${address}`} target="_blank" rel="noreferrer" title={address}>{label ?? shortAddress(address)} <ArrowUpRight size={12}/></a>; }
function EmptyState({ title, children }: { title: string; children: ReactNode }) { return <div className="rewards-empty"><FileCheck2 size={28}/><h3>{title}</h3><p>{children}</p></div>; }
function Field({ label, hint, children, wide = false }: { label: string; hint?: ReactNode; children: ReactNode; wide?: boolean }) { return <label className={`rewards-field ${wide ? "is-wide" : ""}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function Split({ holderBps, devBps, treasuryBps }: { holderBps: number; devBps: number; treasuryBps: number }) {
  return <div className="rewards-split"><div className="rewards-split-track" role="img" aria-label={`${percent(holderBps)} to token holders, ${percent(devBps)} to the developer wallet, ${percent(treasuryBps)} to the treasury`}><span style={{ width: `${holderBps / 100}%` }}/><span style={{ width: `${devBps / 100}%` }}/><span style={{ width: `${treasuryBps / 100}%` }}/></div><div className="rewards-split-labels"><div><strong>{percent(holderBps)}</strong><span><i/>Token holders</span></div><div><strong>{percent(devBps)}</strong><span><i/>Developer wallet</span></div><div><strong>{percent(treasuryBps)}</strong><span><i/>Treasury</span></div></div></div>;
}

type LaunchDraft = {
  name: string; symbol: string; description: string; imageURI: string;
  website: string; twitter: string; telegram: string; developerBuy: string; launchConfigId: string; buybackEnabled: boolean;
  creatorTaxPercent: string; payoutAsset: "ETH" | "USDG";
  owner: string; operator: string; guardian: string; devWallet: string; treasuryWallet: string;
  holderPercent: string; devPercent: string; treasuryPercent: string;
  intervalMinutes: string; rootDelayMinutes: string; minimumIncome: string;
};
const launchDefaults: LaunchDraft = { name: "", symbol: "", description: "", imageURI: "", website: "", twitter: "https://x.com/spreadonrh", telegram: "", developerBuy: "0", launchConfigId: "0", buybackEnabled: false, creatorTaxPercent: "1", payoutAsset: "ETH", owner: "", operator: "", guardian: "", devWallet: "", treasuryWallet: "", holderPercent: "75", devPercent: "5", treasuryPercent: "20", intervalMinutes: "15", rootDelayMinutes: "15", minimumIncome: "0.001" };
const draftKey = "spreadline.token-launch.draft.v1";
function readBps(value: string) { if (!/^\d{1,3}(\.\d{1,2})?$/.test(value)) return null; const number = Math.round(Number(value) * 100); return number >= 0 && number <= 10000 ? number : null; }
function validRecipient(value: string) { return isAddress(value) && value.toLowerCase() !== zeroAddress; }
function launchErrors(draft: LaunchDraft, launchState?: PonsLaunchState) {
  const issues: string[] = [];
  if (!draft.name.trim() || draft.name.trim().length > 64) issues.push("Enter a token name of 1–64 characters.");
  if (!/^[A-Z0-9]{1,12}$/.test(draft.symbol)) issues.push("Use a ticker of 1–12 uppercase letters or numbers.");
  if (!draft.description.trim() || draft.description.length > 1000) issues.push("Add a description of 1–1,000 characters.");
  if (!/^(https:\/\/|ipfs:\/\/)/.test(draft.imageURI)) issues.push("Add an HTTPS or IPFS token image URL.");
  for (const [label, value] of [["Website", draft.website], ["X", draft.twitter], ["Telegram", draft.telegram]]) if (value && !/^https:\/\//.test(value)) issues.push(`${label} must be an HTTPS URL.`);
  for (const key of ["owner", "operator", "guardian", "devWallet", "treasuryWallet"] as const) if (!validRecipient(draft[key])) issues.push(`Enter a valid ${key.replace(/([A-Z])/g, " $1").toLowerCase()} address.`);
  const parts = [readBps(draft.holderPercent), readBps(draft.devPercent), readBps(draft.treasuryPercent)];
  if (parts.some((part) => part == null) || parts.reduce<number>((sum, part) => sum + (part ?? 0), 0) !== 10000 || parts[0] === 0) issues.push("The holder, developer and treasury shares must total 100%, with a positive holder share.");
  if (readBps(draft.creatorTaxPercent) == null) issues.push("Enter a valid creator fee percentage, using up to two decimal places.");
  if (launchState?.maxCreatorTaxBps != null && (readBps(draft.creatorTaxPercent) ?? 10001) > launchState.maxCreatorTaxBps) issues.push(`The creator trading fee exceeds the current Pons limit of ${percent(launchState.maxCreatorTaxBps)}.`);
  if (launchState?.status === "ready" && !launchState.configs.some((config) => config.id === draft.launchConfigId && config.enabled)) issues.push("Choose an enabled Pons launch configuration.");
  if (!/^\d+(?:\.\d+)?$/.test(draft.developerBuy) || (draft.developerBuy.split(".")[1]?.length ?? 0) > (draft.payoutAsset === "ETH" ? 18 : 6)) issues.push("Enter a valid optional opening purchase amount.");
  const interval = Number(draft.intervalMinutes) * 60, delay = Number(draft.rootDelayMinutes) * 60;
  if (!Number.isInteger(interval) || interval < 60 || interval > 2592000) issues.push("Set the distribution interval between 1 minute and 30 days.");
  if (!Number.isInteger(delay) || delay < 900 || delay > 604800) issues.push("Set the review delay between 15 minutes and 7 days.");
  try { const decimals = draft.payoutAsset === "ETH" ? 18 : 6; const value = parseUnits(draft.minimumIncome, decimals); if (!/^\d+(\.\d+)?$/.test(draft.minimumIncome) || (draft.minimumIncome.split(".")[1]?.length ?? 0) > decimals || value <= BigInt(0) || value > (BigInt(1) << BigInt(128)) - BigInt(1)) issues.push("Enter a positive minimum distribution amount without extra decimal places."); } catch { issues.push("Enter a valid minimum distribution amount."); }
  return issues;
}

function LaunchSetup({ distributor, account }: { distributor: string | null; account: string | null }) {
  const [draft, setDraft] = useState<LaunchDraft>(launchDefaults);
  const [feedback, setFeedback] = useState("");
  const [showErrors, setShowErrors] = useState(false);
  const launch = useQuery({ queryKey: ["token-rewards-launch", account], queryFn: ({ signal }) => getData<PonsLaunchState>(`rewards/launch${account ? `?address=${account}` : ""}`, signal), staleTime: 30000, refetchInterval: (q) => pollingInterval(30000, q.state.error, q.state.fetchFailureCount) });
  const errors = launchErrors(draft, launch.data);
  const config = launch.data?.configs.find((item) => item.id === draft.launchConfigId);
  const creatorBps = readBps(draft.creatorTaxPercent);
  const totalFeeBps = config && creatorBps != null ? config.curveFeeBps + creatorBps : null;
  const update = (key: keyof LaunchDraft, value: string | boolean) => { setDraft((current) => ({ ...current, [key]: value })); setFeedback(""); };
  function saveDraft() { try { localStorage.setItem(draftKey, JSON.stringify(draft)); setFeedback("Draft saved in this browser. Live contract settings are unchanged."); } catch { setFeedback("Browser storage is unavailable. Export the configuration to keep a copy."); } }
  function loadDraft() { try { const value: unknown = JSON.parse(localStorage.getItem(draftKey) ?? "null"); if (!value || typeof value !== "object") { setFeedback("No saved launch draft was found in this browser."); return; } const clean = { ...launchDefaults }; for (const key of Object.keys(launchDefaults) as (keyof LaunchDraft)[]) if (key in value && typeof value[key as keyof typeof value] === "string") Object.assign(clean, { [key]: String(value[key as keyof typeof value]).slice(0, 1200) }); if ("buybackEnabled" in value && typeof value.buybackEnabled === "boolean") clean.buybackEnabled = value.buybackEnabled; if (clean.payoutAsset !== "ETH" && clean.payoutAsset !== "USDG") clean.payoutAsset = "ETH"; setDraft(clean); setFeedback("Saved draft loaded. Review every field before exporting."); } catch { setFeedback("This browser's saved draft could not be read."); } }
  function exportDraft() {
    setShowErrors(true);
    if (errors.length) return;
    const configuration: PonsLaunchDraft & { guardian: string } = { name: draft.name.trim(), symbol: draft.symbol, description: draft.description.trim(), imageURI: draft.imageURI, website: draft.website, twitter: draft.twitter, telegram: draft.telegram, creatorTaxBps: readBps(draft.creatorTaxPercent)!, rewardAsset: draft.payoutAsset === "ETH" ? zeroAddress : USDG, owner: draft.owner, operator: draft.operator, guardian: draft.guardian, developerWallet: draft.devWallet, treasuryWallet: draft.treasuryWallet, holderBps: readBps(draft.holderPercent)!, devBps: readBps(draft.devPercent)!, treasuryBps: readBps(draft.treasuryPercent)!, intervalSeconds: Number(draft.intervalMinutes) * 60, rootDelaySeconds: Number(draft.rootDelayMinutes) * 60, minimumIncome: parseUnits(draft.minimumIncome, draft.payoutAsset === "ETH" ? 18 : 6).toString(), developerBuy: draft.developerBuy, buybackEnabled: draft.buybackEnabled, launchConfigId: draft.launchConfigId };
    const blob = new Blob([`${JSON.stringify(configuration, null, 2)}\n`], { type: "application/json" });
    const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `spreadline-${draft.symbol.toLowerCase()}-launch-draft.json`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); setFeedback("Launch configuration exported. Exporting does not deploy contracts or launch a token.");
  }
  return <>{(launch.error || launch.data?.status === "unavailable") && <Notice warning>{launch.error?.message ?? launch.data?.message}</Notice>}<Notice><strong>Launch configuration · draft.</strong> These settings prepare your Pons token and its fee distributor. They do not change a deployed token. The creator trading fee is fixed at launch; the distribution policy can be changed later by its owner.</Notice><div className="rewards-form-grid"><section className="rewards-panel"><div className="rewards-heading"><div><h2>Make the launch yours</h2><p>Token identity, fee routing and the first distribution policy.</p></div><Coins size={21}/></div><div className="rewards-form-body"><div className="rewards-fields"><Field label="Token name"><input value={draft.name} maxLength={64} placeholder="Your token name" onChange={(event) => update("name", event.target.value)}/></Field><Field label="Ticker"><input value={draft.symbol} maxLength={12} placeholder="TICKER" onChange={(event) => update("symbol", event.target.value.toUpperCase())}/></Field><Field label="Description" wide><textarea value={draft.description} maxLength={1000} placeholder="What your token represents" onChange={(event) => update("description", event.target.value)}/></Field><Field label="Token image URL" hint="Use a publicly accessible HTTPS or IPFS image." wide><input value={draft.imageURI} type="url" placeholder="https://…" onChange={(event) => update("imageURI", event.target.value)}/></Field><Field label="Creator trading fee (%)" hint={launch.data?.maxCreatorTaxBps == null ? "Pons limits are read before launch. This is separate from the distribution split." : `Current Pons maximum: ${percent(launch.data.maxCreatorTaxBps)}. Fixed at launch.`}><input value={draft.creatorTaxPercent} inputMode="decimal" onChange={(event) => update("creatorTaxPercent", event.target.value)}/></Field><Field label="Fee and payout asset" hint="Rewards are paid in the collected asset; no automatic currency conversion."><select value={draft.payoutAsset} onChange={(event) => { update("payoutAsset", event.target.value); update("minimumIncome", event.target.value === "ETH" ? "0.001" : "1"); }}><option value="ETH">ETH · native</option><option value="USDG">USDG · stablecoin</option></select></Field></div><div className="rewards-form-divider"><h3>Launch details</h3><p>Choose a Pons curve and how its base trading fees are used.</p></div><div className="rewards-fields"><Field label="Launch configuration"><select value={draft.launchConfigId} onChange={(event) => update("launchConfigId", event.target.value)}>{launch.data?.configs.length ? launch.data.configs.filter((item) => item.enabled).map((item) => <option key={item.id} value={item.id}>Configuration {item.id} · {rewardAmount(item.supplyRaw, 18, 0)} tokens</option>) : <option value="0">Configuration 0 · awaiting Pons</option>}</select></Field><Field label="Pons buybacks" hint="Buybacks use part of the creator base-fee share. Creator tax still goes to the distributor."><select value={draft.buybackEnabled ? "on" : "off"} onChange={(event) => update("buybackEnabled", event.target.value === "on")}><option value="off">Off · more fees for distribution</option><option value="on">On · split fees with buybacks</option></select></Field><Field label="Website"><input value={draft.website} type="url" placeholder="https://…" onChange={(event) => update("website", event.target.value)}/></Field><Field label="X profile"><input value={draft.twitter} type="url" placeholder="https://x.com/…" onChange={(event) => update("twitter", event.target.value)}/></Field><Field label="Telegram"><input value={draft.telegram} type="url" placeholder="https://t.me/…" onChange={(event) => update("telegram", event.target.value)}/></Field><Field label={`Optional opening purchase (${draft.payoutAsset})`} hint="Defaults to zero. Any purchase requires a separate spend and minimum-output review."><input value={draft.developerBuy} inputMode="decimal" onChange={(event) => update("developerBuy", event.target.value)}/></Field></div><div className="rewards-form-divider"><h3>Wallets with a purpose</h3><p>The distributor contract receives creator fees. Developer and treasury wallets receive their configured shares.</p>{account && <button className="rewards-text-button" style={{ marginTop: 10 }} onClick={() => { setDraft((current) => ({ ...current, owner: account, guardian: account })); setFeedback(""); }}>Use connected wallet as owner and guardian <ArrowRight size={12}/></button>}</div><div className="rewards-fields">{([['owner', 'Owner wallet', 'Controls future policies and administrative roles.'], ['operator', 'Distribution operator', 'Publishes holder snapshots and runs scheduled payouts.'], ['guardian', 'Guardian wallet', 'Can pause new distributions; only the owner can resume.'], ['devWallet', 'Developer wallet', 'Receives the developer share of activated distributions.'], ['treasuryWallet', 'Treasury wallet', 'Receives the treasury share of activated distributions.']] as const).map(([key, label, hint]) => <Field key={key} label={label} hint={hint} wide><input value={draft[key]} spellCheck={false} autoComplete="off" placeholder="0x…" onChange={(event) => update(key, event.target.value)}/></Field>)}</div><div className="rewards-form-divider"><h3>Initial reward policy</h3><p>All three shares must total 100%. The owner can update this policy for future distributions.</p></div><div className="rewards-fields"><Field label="Token holders (%)"><input value={draft.holderPercent} inputMode="decimal" onChange={(event) => update("holderPercent", event.target.value)}/></Field><Field label="Developer (%)"><input value={draft.devPercent} inputMode="decimal" onChange={(event) => update("devPercent", event.target.value)}/></Field><Field label="Treasury (%)"><input value={draft.treasuryPercent} inputMode="decimal" onChange={(event) => update("treasuryPercent", event.target.value)}/></Field><Field label="Distribution interval (minutes)" hint="Earliest time between proposals. Distribution also requires sufficient fees and a running operator."><input value={draft.intervalMinutes} inputMode="decimal" onChange={(event) => update("intervalMinutes", event.target.value)}/></Field><Field label="Public review delay (minutes)" hint="At least 15 minutes to review each proposed holder snapshot before activation."><input value={draft.rootDelayMinutes} inputMode="decimal" onChange={(event) => update("rootDelayMinutes", event.target.value)}/></Field><Field label={`Minimum distribution (${draft.payoutAsset})`}><input value={draft.minimumIncome} inputMode="decimal" onChange={(event) => update("minimumIncome", event.target.value)}/></Field></div>{showErrors && errors.length > 0 && <div className="rewards-error" role="alert"><p className="rewards-error">Complete the following before exporting:</p><ul>{errors.map((error) => <li key={error}>{error}</li>)}</ul></div>}<div className="rewards-form-actions"><button className="rewards-button" onClick={exportDraft}><Download size={14}/>Export launch configuration</button><button className="rewards-button is-quiet" onClick={saveDraft}><Save size={14}/>Save draft</button><button className="rewards-text-button" onClick={loadDraft}>Load saved draft</button></div>{feedback && <p className="rewards-form-feedback" role="status">{feedback}</p>}</div></section><aside className="rewards-panel rewards-draft-preview"><span className="rewards-tag">Draft · not onchain</span><h3>{draft.name.trim() || "Your token, shared rewards."}</h3><p>{draft.symbol ? `$${draft.symbol} · ` : ""}{draft.description.trim() || "Creator trading fees flow into an auditable pool for your token holders."}</p><dl className="rewards-preview-list"><div><dt>Network</dt><dd>Robinhood Chain</dd></div><div><dt>Creator trading tax</dt><dd>{draft.creatorTaxPercent || "—"}%</dd></div><div><dt>Base trading fee</dt><dd>{config ? percent(config.curveFeeBps) : "Awaiting Pons"}</dd></div><div><dt>Total curve trading fee</dt><dd>{totalFeeBps == null ? "—" : percent(totalFeeBps)}</dd></div><div><dt>Pons launch fee</dt><dd>{rewardAmount(launch.data?.launchFeeWei, 18)} ETH</dd></div><div><dt>Buybacks</dt><dd>{draft.buybackEnabled ? "Enabled" : "Disabled"}</dd></div><div><dt>Payout asset</dt><dd>{draft.payoutAsset}</dd></div><div><dt>Holder / dev / treasury</dt><dd>{draft.holderPercent}% / {draft.devPercent}% / {draft.treasuryPercent}%</dd></div><div><dt>Distribution interval</dt><dd>{draft.intervalMinutes || "—"} minutes</dd></div><div><dt>Public review delay</dt><dd>{draft.rootDelayMinutes || "—"} minutes</dd></div><div><dt>Fee recipient</dt><dd>{distributor ? <AddressLink address={distributor}/> : "Distributor not configured"}</dd></div></dl><p className="rewards-preview-note">{launch.data?.feePolicy && config ? `Pons takes ${percent(launch.data.feePolicy.protocolFeeShareBps)} of the base trading fee. ${draft.buybackEnabled ? `${percent(launch.data.feePolicy.buybackBurnBps)} of the remaining base fee funds buybacks; the rest and all creator tax fund the distributor.` : "The remaining base fee and all creator tax fund the distributor."}` : "The final launch preview reads the current factory and shows the complete cost before signing."}</p>{launch.data && <p style={{ fontSize: 10, marginTop: 12 }}>Pons read at block {launch.data.blockNumber ?? "—"}. {launch.data.launchEnabled === false ? "New launches are disabled." : account && launch.data.canLaunch === false ? "The connected wallet is not permitted to launch." : ""} <a className="rewards-text-button" href={launch.data.docsUrl} target="_blank" rel="noreferrer">Pons documentation <ArrowUpRight size={11}/></a></p>}<div className="rewards-form-divider"><h3 style={{ font: "500 14px Arial, Helvetica, sans-serif" }}>Launch in the right order</h3></div><ol className="rewards-steps"><li><strong>Deploy the distributor</strong><p>Set the payout asset, verified Pons escrow, owner, operator and initial policy.</p></li><li><strong>Launch your token on Pons</strong><p>Set the distributor contract as the creator fee recipient. Sending fees to a personal wallet bypasses holder accounting.</p></li><li><strong>Bind the launched token</strong><p>The owner connects the verified token address to its distributor exactly once.</p></li><li><strong>Review, then enable distributions</strong><p>Configure eligibility and scheduling, verify collected fees, and enable the operator after reviewing the deployed system.</p></li></ol></aside></div></>;
}

function HolderClaim({ snapshot, wallet, claim, refresh }: { snapshot: RewardsSnapshot | undefined; wallet: WalletState; claim: RewardClaim; refresh: () => void }) {
  const [redirect, setRedirect] = useState(false);
  const [receiver, setReceiver] = useState("");
  return <div className="rewards-holder-claim"><RewardsAction wallet={wallet} snapshot={snapshot} request={redirect ? { kind: "claim-to", claim, receiver: receiver as `0x${string}` } : { kind: "claim", claim }} onConfirmed={refresh} label={redirect ? `Claim #${claim.epochId} to receiver` : `Claim #${claim.epochId}`} disabled={redirect && (!validRecipient(receiver) || receiver.toLowerCase() === snapshot?.distributor?.address.toLowerCase())}/><button className="rewards-text-button" style={{ marginTop: 12 }} onClick={() => setRedirect((current) => !current)}>{redirect ? "Receive in my connected wallet" : "Use another receiving wallet"}</button>{redirect && <div style={{ marginTop: 14 }}><Field label="Receiving wallet" hint="Use this if your connected smart wallet cannot receive ETH. The connected holder signs to redirect their own allocation."><input value={receiver} onChange={(event) => setReceiver(event.target.value)} spellCheck={false} autoComplete="off" placeholder="0x…"/></Field></div>}</div>;
}

function RewardOverview({ snapshot, wallet, now, refresh }: { snapshot: RewardsSnapshot | undefined; wallet: WalletState; now: number; refresh: () => void }) {
  const contract = snapshot?.distributor, asset = contract?.rewardSymbol ?? "ETH", decimals = contract?.rewardDecimals ?? 18;
  const personal = snapshot?.wallet?.address.toLowerCase() === wallet.account?.toLowerCase() ? snapshot?.wallet : null;
  const claims = personal?.claims.filter((claim) => !claim.claimed && BigInt(claim.amount) > BigInt(0)) ?? [];
  const pending = snapshot?.epochs.filter((epoch) => epoch.state === "proposed").sort((a, b) => a.readyAt - b.readyAt)[0];
  const policy = contract?.policy;
  const nextProposal = contract?.lastProposedAt && policy ? contract.lastProposedAt + policy.intervalSeconds : null;
  const tokenBound = contract && contract.holderToken.toLowerCase() !== zeroAddress;
  const lastClaimable = claims.reduce((sum, claim) => sum + BigInt(claim.amount), BigInt(0));
  return <><div className="rewards-overview"><section className="rewards-panel"><div className="rewards-heading"><div><h2>Trading fees, shared.</h2><p>Track collected revenue and money actually paid to holders.</p></div><Coins size={22}/></div><div className="rewards-total"><span>Paid to token holders</span><strong>{rewardAmount(contract?.totalHolderPaid, decimals)}<small>{asset}</small></strong><p>Confirmed holder payments. Reserved or proposed rewards are reported separately.</p></div><div className="rewards-metrics"><div><span>Pons fees collected</span><strong>{rewardAmount(contract?.totalPonsCollected, decimals)} <small style={{ display: "inline" }}>{asset}</small></strong><small>Fees received from the Pons escrow.</small></div><div><span>Allocated to holders</span><strong>{rewardAmount(contract?.totalHolderAllocated, decimals)} <small style={{ display: "inline" }}>{asset}</small></strong><small>Activated distributions, including paid rewards.</small></div><div><span>Available for distribution</span><strong>{rewardAmount(contract?.availableIncome, decimals)} <small style={{ display: "inline" }}>{asset}</small></strong><small>Cash remaining after all reserved allocations.</small></div><div><span>Accrued at Pons</span><strong>{rewardAmount(contract?.escrowCredit, decimals)} <small style={{ display: "inline" }}>{asset}</small></strong><small>Escrow credit awaiting collection into the distributor.</small></div></div><div className="rewards-panel-footer"><span>{contract ? <>Distributor · <AddressLink address={contract.address}/></> : "Distributor not configured"}</span><span>{contract ? `Policy version ${contract.policyVersion}` : "No live policy"}</span></div></section><section className="rewards-panel rewards-participation"><span className="rewards-tag"><Users size={12}/>{tokenBound ? `${contract.holderTokenSymbol} holder rewards` : "Token holder rewards"}</span><h2>Your share of the fees.</h2>{!contract ? <><p>The reward distributor and launch token are not connected yet. Once active, each distribution records eligible token balances and reserves their share of collected fees.</p><p className="rewards-wallet-note">No income has been assumed. The live totals will appear after the distributor is configured and verified.</p></> : !wallet.account ? <><p>Connect your wallet to see your token balance, distribution eligibility and claimable rewards.</p><WalletButton wallet={wallet}/><p className="rewards-wallet-note">Rewards depend on collected fees and your eligible balance at each published snapshot. Holding a token does not guarantee income.</p></> : <><span className="rewards-account"><WalletIcon size={12}/>{shortAddress(wallet.account)}</span><strong className="rewards-claim-amount">{personal ? rewardAmount(lastClaimable.toString(), decimals) : "—"}<small>{asset} claimable</small></strong><p>{personal ? `${rewardAmount(personal.holderBalance, contract.holderTokenDecimals, 4)} ${contract.holderTokenSymbol} held now` : "Reading your holder balance…"}. Each distribution uses its recorded snapshot balance.</p>{wallet.chainId !== CHAIN_ID && <button className="rewards-button" onClick={() => void wallet.switchNetwork()} disabled={wallet.pending}>Switch to Robinhood Chain</button>}{personal?.proofsStatus === "unavailable" && <Notice>{personal.proofsMessage}</Notice>}{claims.slice(0, 3).map((claim) => <div className="rewards-claim-row" key={claim.epochId}><div><strong>Distribution #{claim.epochId}</strong><p>{rewardAmount(claim.amount, decimals)} {asset} · verified claim proof</p></div><HolderClaim wallet={wallet} snapshot={snapshot} claim={claim} refresh={refresh}/></div>)}{personal && !claims.length && personal.proofsStatus !== "unavailable" && <p>{personal.proofsMessage || "No unpaid rewards were found in the distributions on this page."}</p>}<p className="rewards-wallet-note">This total covers the loaded distributions. Browse older distributions to find earlier unpaid claims. Operator payments and wallet claims use the same entitlement, so it can be paid only once.</p></>}</section></div><section className="rewards-panel rewards-policy"><div className="rewards-heading"><div><h2>Where each distribution goes</h2><p>{policy ? "The current onchain policy applies to newly proposed distributions." : "Proposed launch defaults. No distribution policy is live yet."}</p></div><span className="rewards-tag">{policy ? "Onchain policy" : "Draft defaults"}</span></div><Split holderBps={policy?.holderBps ?? 7500} devBps={policy?.devBps ?? 500} treasuryBps={policy?.treasuryBps ?? 2000}/><div className="rewards-schedule"><div><span><CalendarClock size={14}/>Distribution interval</span><strong>{policy ? duration(policy.intervalSeconds) : "15 minutes · draft"}</strong><small>{pending ? `Next activation from ${timestamp(pending.readyAt)}` : nextProposal ? nextProposal * 1000 <= now ? "Interval elapsed; awaiting funded proposal" : `Earliest proposal ${timestamp(nextProposal)}` : "Schedule starts with the first proposal"}</small></div><div><span><Clock3 size={14}/>Public review delay</span><strong>{policy ? duration(policy.rootDelaySeconds) : "15 minutes · draft"}</strong><small>Snapshots are visible before a distribution becomes claimable.</small></div><div><span><Coins size={14}/>Minimum collected income</span><strong>{policy ? `${rewardAmount(policy.minimumIncome, decimals)} ${asset}` : "Set in launch configuration"}</strong><small>{contract?.paused ? "New proposals and activations are paused." : "A running operator and sufficient collected fees are required."}</small></div></div><div className="rewards-panel-footer"><span>Developer paid: {rewardAmount(contract?.totalDevPaid, decimals)} {asset}</span><span>Treasury paid: {rewardAmount(contract?.totalTreasuryPaid, decimals)} {asset}</span></div></section><section className="rewards-panel rewards-flow" aria-label="How creator fees become holder rewards"><div><Coins size={26}/><h3>1. Trading creates fees</h3><p>Pons credits the configured creator fee recipient when eligible token trades occur. The distributor collects those fees in the payout asset.</p><ArrowRight className="rewards-flow-arrow" size={17}/></div><div><FileCheck2 size={26}/><h3>2. A snapshot fixes each share</h3><p>The operator publishes eligible balances, exclusions and an auditable distribution manifest. A public delay allows review before activation.</p><ArrowRight className="rewards-flow-arrow" size={17}/></div><div><Users size={26}/><h3>3. Holders receive their allocation</h3><p>The operator can pay wallets in batches. Eligible holders can also claim directly. Developer and treasury allocations follow the same recorded split.</p></div></section></>;
}

function DistributionHistory({ snapshot, wallet, now, refresh, older, newer, hasNewer }: { snapshot: RewardsSnapshot | undefined; wallet: WalletState; now: number; refresh: () => void; older: () => void; newer: () => void; hasNewer: boolean }) {
  const contract = snapshot?.distributor, asset = contract?.rewardSymbol ?? "ETH", decimals = contract?.rewardDecimals ?? 18;
  const canCancel = !!wallet.account && !!contract && [contract.owner, contract.guardian].some((address) => address.toLowerCase() === wallet.account!.toLowerCase());
  return <><Notice>Each distribution records a holder snapshot, a funded budget and its own policy version. The operator publishes the eligible balances; the contract verifies submitted proofs and enforces reserved budgets.</Notice><section className="rewards-panel"><div className="rewards-heading"><div><h2>Distribution history</h2><p>Published allocations and the evidence behind every payment.</p></div><span className="rewards-tag">{snapshot?.epochs.length ?? 0} loaded</span></div>{snapshot?.epochs.length ? snapshot.epochs.map((epoch) => {
    const claim = snapshot.wallet?.claims.find((item) => item.epochId === epoch.id && item.account.toLowerCase() === wallet.account?.toLowerCase());
    return <article className="rewards-epoch" key={epoch.id}><div className="rewards-epoch-heading"><div><h3>Distribution #{epoch.id}</h3><span className="rewards-tag">{epoch.state === "active" ? <Check size={11}/> : epoch.state === "proposed" ? <Clock3 size={11}/> : null}{epoch.state === "active" ? "Active · claimable" : epoch.state === "proposed" ? "Proposed · under review" : "Cancelled"}</span></div><span style={{ fontSize: 10, color: "var(--reward-muted)" }}>{timestamp(epoch.proposedAt)}</span></div><div className="rewards-epoch-metrics"><div><span>Distribution income</span><strong>{rewardAmount(epoch.grossIncome, decimals)} {asset}</strong></div><div><span>Holder allocation</span><strong>{rewardAmount(epoch.holderBudget, decimals)} {asset}</strong></div><div><span>Paid to holders</span><strong>{rewardAmount(epoch.holderPaid, decimals)} {asset}</strong></div><div><span>Developer / treasury</span><strong>{rewardAmount(epoch.devBudget, decimals)} / {rewardAmount(epoch.treasuryBudget, decimals)} {asset}</strong></div></div><details className="rewards-epoch-details"><summary>Inspect snapshot and policy</summary><dl className="rewards-audit"><dt>Snapshot block</dt><dd><a href={`${EXPLORER}/block/${epoch.snapshotBlock}`} target="_blank" rel="noreferrer">{epoch.snapshotBlock}<ArrowUpRight size={11}/></a></dd><dt>Snapshot hash</dt><dd>{epoch.snapshotBlockHash}</dd><dt>Merkle root</dt><dd>{epoch.root}</dd><dt>Manifest hash</dt><dd>{epoch.manifestHash}</dd><dt>Policy version</dt><dd>{epoch.policyVersion}</dd><dt>Review ends</dt><dd>{timestamp(epoch.readyAt)}</dd><dt>Developer wallet</dt><dd><AddressLink address={epoch.devWallet}/></dd><dt>Treasury wallet</dt><dd><AddressLink address={epoch.treasuryWallet}/></dd><dt>Audit manifest</dt><dd>{snapshot.manifestsAvailable ? <a href={`/api/rewards/manifest?epoch=${encodeURIComponent(epoch.id)}`} target="_blank" rel="noreferrer">Open committed manifest<ExternalLink size={11}/></a> : "Manifest storage is not available"}</dd></dl></details>{claim && !claim.claimed && BigInt(claim.amount) > BigInt(0) && <div className="rewards-claim-row" style={{ marginTop: 17 }}><div><strong>Your allocation: {rewardAmount(claim.amount, decimals)} {asset}</strong><p>Paid to {shortAddress(claim.account)} after a confirmed claim.</p></div><HolderClaim wallet={wallet} snapshot={snapshot} claim={claim} refresh={refresh}/></div>}{claim?.claimed && <p style={{ fontSize: 10, marginTop: 16 }}>Your allocation has already been paid.</p>}{epoch.state === "proposed" && wallet.account && <div style={{ display: "flex", flexWrap: "wrap", gap: 14 }}><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "activate", epochId: epoch.id }} onConfirmed={refresh} label={`Activate #${epoch.id}`} disabled={!!contract?.paused || epoch.readyAt * 1000 > now}/>{canCancel && <RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "cancel", epochId: epoch.id }} onConfirmed={refresh} label={`Cancel #${epoch.id}`}/>}</div>}</article>;
  }) : <EmptyState title="The first distribution starts the record.">{snapshot?.status === "ready" ? "Collected fees need to meet the minimum income threshold before the operator can propose a holder snapshot." : "Confirmed distributions will appear after the reward distributor is configured."}</EmptyState>}<div className="rewards-panel-footer"><button className="rewards-text-button" disabled={!hasNewer} onClick={newer}>Newer distributions</button><span>Earlier unpaid allocations remain claimable.</span><button className="rewards-text-button" disabled={!snapshot?.nextEpochCursor} onClick={older}>Older distributions <ArrowRight size={12}/></button></div></section>{snapshot?.eventsError && <Notice>{snapshot.eventsError}</Notice>}{!!snapshot?.events.length && <section className="rewards-panel" style={{ marginTop: 20 }}><div className="rewards-heading"><div><h2>Recent onchain activity</h2><p>Transaction receipts from the configured distributor.</p></div></div>{snapshot.events.map((event) => <div className="rewards-epoch" key={event.id} style={{ display: "flex", justifyContent: "space-between", gap: 20 }}><div><h3>{({ collected: "Pons fees collected", proposed: "Distribution proposed", activated: "Distribution activated", cancelled: "Distribution cancelled", "holder-paid": "Holder paid", "dev-paid": "Developer paid", "treasury-paid": "Treasury paid", policy: "Policy updated" })[event.kind]}{event.epochId ? ` · #${event.epochId}` : ""}</h3><p style={{ fontSize: 10, marginTop: 6 }}>Block {event.blockNumber}{event.account ? ` · ${shortAddress(event.account)}` : ""}</p></div><a className="rewards-text-button" href={`${EXPLORER}/tx/${event.transactionHash}`} target="_blank" rel="noreferrer">{event.amount == null ? "Receipt" : `${rewardAmount(event.amount, decimals)} ${asset}`}<ArrowUpRight size={13}/></a></div>)}</section>}</>;
}

function PolicyForm({ snapshot, wallet, refresh }: { snapshot: RewardsSnapshot; wallet: WalletState; refresh: () => void }) {
  const contract = snapshot.distributor!, policy = contract.policy;
  const [form, setForm] = useState({ holderPercent: String(policy.holderBps / 100), devPercent: String(policy.devBps / 100), treasuryPercent: String(policy.treasuryBps / 100), intervalMinutes: String(policy.intervalSeconds / 60), rootDelayMinutes: String(policy.rootDelaySeconds / 60), minimumIncome: formatUnits(BigInt(policy.minimumIncome), contract.rewardDecimals), devWallet: policy.devWallet as string, treasuryWallet: policy.treasuryWallet as string });
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  let nextPolicy: RewardPolicy | null = null, error: string | null = null;
  try {
    const holderBps = readBps(form.holderPercent), devBps = readBps(form.devPercent), treasuryBps = readBps(form.treasuryPercent);
    if (holderBps == null || devBps == null || treasuryBps == null) throw new Error("Use percentages with up to two decimal places.");
    if (!new RegExp(`^\\d+(?:\\.\\d{1,${contract.rewardDecimals}})?$`).test(form.minimumIncome)) throw new Error(`Enter a minimum income with up to ${contract.rewardDecimals} decimal places.`);
    nextPolicy = { holderBps, devBps, treasuryBps, intervalSeconds: Number(form.intervalMinutes) * 60, rootDelaySeconds: Number(form.rootDelayMinutes) * 60, minimumIncome: parseUnits(form.minimumIncome, contract.rewardDecimals).toString(), devWallet: form.devWallet as `0x${string}`, treasuryWallet: form.treasuryWallet as `0x${string}` };
    validateRewardPolicy(nextPolicy, contract.address);
  } catch (reason) { error = reason instanceof Error ? reason.message : "Review the policy fields."; nextPolicy = null; }
  return <section className="rewards-panel"><div className="rewards-heading"><div><h2>Distribution policy</h2><p>Set the split, timing and destination wallets for future proposals.</p></div><Settings2 size={21}/></div><div className="rewards-form-body"><div className="rewards-fields"><Field label="Token holders (%)"><input value={form.holderPercent} inputMode="decimal" onChange={(event) => update("holderPercent", event.target.value)}/></Field><Field label="Developer (%)"><input value={form.devPercent} inputMode="decimal" onChange={(event) => update("devPercent", event.target.value)}/></Field><Field label="Treasury (%)"><input value={form.treasuryPercent} inputMode="decimal" onChange={(event) => update("treasuryPercent", event.target.value)}/></Field><Field label="Distribution interval (minutes)" hint="From 1 minute to 30 days. The operator also checks available income."><input value={form.intervalMinutes} inputMode="decimal" onChange={(event) => update("intervalMinutes", event.target.value)}/></Field><Field label="Public review delay (minutes)" hint="From 15 minutes to 7 days."><input value={form.rootDelayMinutes} inputMode="decimal" onChange={(event) => update("rootDelayMinutes", event.target.value)}/></Field><Field label={`Minimum income (${contract.rewardSymbol})`}><input value={form.minimumIncome} inputMode="decimal" onChange={(event) => update("minimumIncome", event.target.value)}/></Field><Field label="Developer wallet" wide><input value={form.devWallet} spellCheck={false} autoComplete="off" onChange={(event) => update("devWallet", event.target.value)}/></Field><Field label="Treasury wallet" wide><input value={form.treasuryWallet} spellCheck={false} autoComplete="off" onChange={(event) => update("treasuryWallet", event.target.value)}/></Field></div><div className="rewards-form-divider"><p>Already proposed or activated distributions retain their original budgets, wallet destinations and policy version. The Pons creator trading fee is fixed at launch and cannot be changed here.</p></div>{error && <p className="rewards-error" role="alert">{error}</p>}<RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "policy", policy: nextPolicy ?? policy }} onConfirmed={refresh} label="Update distribution policy" disabled={!nextPolicy}/></div></section>;
}

function CashWithdrawal({ snapshot, wallet, refresh }: { snapshot: RewardsSnapshot; wallet: WalletState; refresh: () => void }) {
  const [redirect, setRedirect] = useState(false); const [receiver, setReceiver] = useState("");
  const hasCash = !!snapshot.wallet && BigInt(snapshot.wallet.pendingDev) + BigInt(snapshot.wallet.pendingTreasury) > BigInt(0);
  return <div className="rewards-holder-claim"><RewardsAction wallet={wallet} snapshot={snapshot} request={redirect ? { kind: "withdraw-cash", receiver: receiver as `0x${string}` } : { kind: "withdraw-cash" }} onConfirmed={refresh} label="Withdraw wallet allocation" disabled={!hasCash || redirect && (!validRecipient(receiver) || receiver.toLowerCase() === snapshot.distributor?.address.toLowerCase())}/><button className="rewards-text-button" style={{ marginTop: 12 }} onClick={() => setRedirect((value) => !value)}>{redirect ? "Receive in my connected wallet" : "Use another receiving wallet"}</button>{redirect && <div style={{ marginTop: 14 }}><Field label="Cash receiving wallet" hint="Only your connected wallet's developer and treasury allocations are withdrawn. Use this if it cannot receive the payout asset."><input value={receiver} onChange={(event) => setReceiver(event.target.value)} spellCheck={false} autoComplete="off" placeholder="0x…"/></Field></div>}</div>;
}

function Administration({ snapshot, wallet, refresh }: { snapshot: RewardsSnapshot | undefined; wallet: WalletState; refresh: () => void }) {
  const contract = snapshot?.distributor;
  const [operator, setOperator] = useState(""); const [guardian, setGuardian] = useState(""); const [token, setToken] = useState(""); const [owner, setOwner] = useState("");
  const isOwner = !!wallet.account && contract?.owner.toLowerCase() === wallet.account.toLowerCase();
  const isGuardian = !!wallet.account && contract?.guardian.toLowerCase() === wallet.account.toLowerCase();
  const isOperator = !!wallet.account && contract?.operator.toLowerCase() === wallet.account.toLowerCase();
  const isPendingOwner = !!wallet.account && contract?.pendingOwner.toLowerCase() === wallet.account.toLowerCase();
  if (!contract || !snapshot) return <section className="rewards-panel"><EmptyState title="Connect the distributor first.">The launch setup prepares owner, operator and payout wallets. Live administration becomes available after a verified distributor is configured.</EmptyState></section>;
  return <><Notice><strong>{isOwner ? "Connected as distributor owner." : isGuardian ? "Connected as guardian." : "Administration is controlled by the onchain owner."}</strong> New policies require a simulated preview and an explicit wallet confirmation. Pausing affects new proposals and activations; existing holder claims and cash withdrawals remain open.</Notice><div className="rewards-admin-grid"><div>{isOwner ? <PolicyForm key={`${contract.policyVersion}:${wallet.account}`} snapshot={snapshot} wallet={wallet} refresh={refresh}/> : <section className="rewards-panel"><div className="rewards-heading"><div><h2>Owner access</h2><p>Connect the owner wallet to edit distribution percentages, timing and recipients.</p><div className="rewards-owner-address"><AddressLink address={contract.owner}/></div></div><LockKeyhole size={22}/></div><div className="rewards-form-body"><WalletButton wallet={wallet}/>{isPendingOwner && <RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "accept-owner" }} onConfirmed={refresh} label="Accept ownership"/>}</div></section>}{isOwner && <section className="rewards-panel" style={{ marginTop: 20 }}><div className="rewards-heading"><div><h2>Operational roles</h2><p>Keep distribution publishing and emergency pausing explicit.</p></div><ShieldCheck size={21}/></div><div className="rewards-control-section"><h3>Distribution operator</h3><p>Currently <AddressLink address={contract.operator}/>. Can publish funded snapshots and sponsor batch payments.</p><Field label="New operator wallet"><input value={operator} onChange={(event) => setOperator(event.target.value)} placeholder="0x…" spellCheck={false}/></Field><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "operator", address: operator as `0x${string}` }} onConfirmed={refresh} label="Update operator" disabled={!validRecipient(operator)}/></div><div className="rewards-control-section"><h3>Guardian</h3><p>Currently <AddressLink address={contract.guardian}/>. Can pause new distributions or cancel a proposed snapshot. Resuming requires the owner.</p><Field label="New guardian wallet"><input value={guardian} onChange={(event) => setGuardian(event.target.value)} placeholder="0x…" spellCheck={false}/></Field><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "guardian", address: guardian as `0x${string}` }} onConfirmed={refresh} label="Update guardian" disabled={!validRecipient(guardian)}/></div><div className="rewards-control-section"><h3>Transfer ownership</h3><p>The receiving wallet must accept the transfer before it takes effect.{contract.pendingOwner.toLowerCase() !== zeroAddress && <> Pending owner: <AddressLink address={contract.pendingOwner}/>.</>}</p><Field label="Proposed owner wallet"><input value={owner} onChange={(event) => setOwner(event.target.value)} placeholder="0x…" spellCheck={false}/></Field><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "propose-owner", address: owner as `0x${string}` }} onConfirmed={refresh} label="Propose new owner" disabled={!validRecipient(owner)}/></div></section>}</div><aside className="rewards-admin-side"><section className="rewards-panel"><div className="rewards-control-section"><h3>Distribution status</h3><p><span className="rewards-tag">{contract.paused ? "New distributions paused" : "New distributions enabled"}</span></p><p>Holder claims and developer or treasury withdrawals remain available while paused.</p>{(isOwner || isGuardian && !contract.paused) && <RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "pause", paused: !contract.paused }} onConfirmed={refresh} label={contract.paused ? "Resume distributions" : "Pause distributions"}/>}</div>{(isOwner || isOperator) && <div className="rewards-control-section"><h3>Move trading fees to escrow</h3><p>The operator normally performs this step. These controls can recover the fee pipeline manually. Preview validates the current launch phase and conversion bounds.</p><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "sweep-curve" }} onConfirmed={refresh} label="Sweep curve fees"/><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "sweep-pool" }} onConfirmed={refresh} label="Sweep pool fees"/></div>}<div className="rewards-control-section"><h3>Pons fee collection</h3><p>{rewardAmount(contract.escrowCredit, contract.rewardDecimals)} {contract.rewardSymbol} credited to this distributor. Anyone can collect its own accrued fees from the verified escrow.</p><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "collect" }} onConfirmed={refresh} label="Collect Pons fees" disabled={contract.escrowCredit === "0"}/></div><div className="rewards-control-section"><h3>Developer and treasury cash</h3><p>Your available allocation: {snapshot.wallet ? rewardAmount((BigInt(snapshot.wallet.pendingDev) + BigInt(snapshot.wallet.pendingTreasury)).toString(), contract.rewardDecimals) : "—"} {contract.rewardSymbol}.</p><CashWithdrawal wallet={wallet} snapshot={snapshot} refresh={refresh}/></div></section><section className="rewards-panel"><div className="rewards-control-section"><h3>Launch token</h3>{contract.holderToken.toLowerCase() === zeroAddress ? <><p>Bind the verified token created on Pons. The holder token can be set exactly once.</p>{isOwner && <><Field label="Launched token address"><input value={token} onChange={(event) => setToken(event.target.value)} placeholder="0x…" spellCheck={false}/></Field><RewardsAction wallet={wallet} snapshot={snapshot} request={{ kind: "bind-token", address: token as `0x${string}` }} onConfirmed={refresh} label="Bind holder token" disabled={!validRecipient(token)}/></>}</> : <p>{contract.holderTokenSymbol} · <AddressLink address={contract.holderToken}/></p>}</div><div className="rewards-control-section"><h3>Fee routing</h3><p>The Pons creator fee recipient must be this distributor. Changes to developer and treasury wallets do not change that recipient.</p><dl className="rewards-preview-list"><div><dt>Distributor</dt><dd><AddressLink address={contract.address}/></dd></div><div><dt>Pons escrow</dt><dd><AddressLink address={contract.ponsEscrow}/></dd></div><div><dt>Payout asset</dt><dd>{contract.rewardAsset.toLowerCase() === zeroAddress ? "Native ETH" : <AddressLink address={contract.rewardAsset} label={contract.rewardSymbol}/>}</dd></div></dl></div></section></aside></div></>;
}

type RewardsTab = "overview" | "distributions" | "launch" | "admin";
const rewardTabs = [{ id: "overview", label: "Overview", icon: Coins }, { id: "distributions", label: "Distributions", icon: FileCheck2 }, { id: "launch", label: "Launch setup", icon: Landmark }, { id: "admin", label: "Administration", icon: Settings2 }] as const;
export function TokenRewards({ wallet, now }: { wallet: WalletState; now: number }) {
  const [tab, setTab] = useState<RewardsTab>("overview");
  const [cursors, setCursors] = useState<string[]>([]);
  const before = cursors.at(-1);
  const query = new URLSearchParams(); if (wallet.account) query.set("address", wallet.account); if (before) query.set("before", before);
  const snapshot = useQuery({ queryKey: ["token-rewards", wallet.account, before], queryFn: ({ signal }) => getData<RewardsSnapshot>(`rewards${query.size ? `?${query}` : ""}`, signal), staleTime: 15000, refetchInterval: (q) => pollingInterval(15000, q.state.error, q.state.fetchFailureCount, q.state.data?.dataStatus?.retryAt) });
  const refetch = snapshot.refetch;
  const refresh = useCallback(() => { void refetch(); }, [refetch]);
  const contract = snapshot.data?.distributor;
  const fresh = snapshot.data?.status === "ready" && !snapshot.error && !snapshot.data.dataStatus && !!snapshot.data.blockTimestamp && now - Date.parse(snapshot.data.blockTimestamp) < 120000;
  return <div className="rewards-workspace"><div className={`rewards-status ${fresh ? "is-live" : ""}`}><div><i/><strong>{snapshot.isPending ? "Reading reward state" : snapshot.data?.status === "unconfigured" ? "Launch configuration pending" : fresh ? "Verified chain snapshot" : "Reward data unavailable"}</strong><span className="rewards-status-block">{snapshot.data?.blockNumber ? `Block ${snapshot.data.blockNumber} · ${ageLabel(snapshot.data.fetchedAt, now)}` : "Robinhood Chain"}</span></div><button className="rewards-button is-quiet" disabled={snapshot.isFetching} onClick={refresh}><RefreshCw size={13} className={snapshot.isFetching ? "spin" : ""}/>{snapshot.isFetching ? "Updating" : "Refresh"}</button></div>{(snapshot.error || snapshot.data?.dataStatus || snapshot.data?.status === "unavailable") && <Notice warning>{snapshot.data ? "Showing the last available snapshot. " : ""}{snapshot.error?.message ?? snapshot.data?.dataStatus?.reason ?? snapshot.data?.message}</Notice>}{snapshot.data?.status === "unconfigured" && <Notice><strong>Ready for launch setup.</strong> {snapshot.data.message}</Notice>}<nav className="rewards-tabs" aria-label="Token rewards sections">{rewardTabs.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setTab(id)} aria-pressed={tab === id}><Icon size={14}/>{label}</button>)}</nav>{tab === "overview" && <><RewardOverview snapshot={snapshot.data} wallet={wallet} now={now} refresh={refresh}/>{!!snapshot.data?.epochs.length && <div className="rewards-panel-footer" style={{ marginTop: 20, borderRadius: 8 }}><span>Review every distribution and find earlier unpaid claims.</span><button className="rewards-text-button" onClick={() => setTab("distributions")}>Browse distributions <ArrowRight size={12}/></button></div>}</>}{tab === "distributions" && <DistributionHistory snapshot={snapshot.data} wallet={wallet} now={now} refresh={refresh} older={() => { if (snapshot.data?.nextEpochCursor) setCursors((current) => [...current, snapshot.data!.nextEpochCursor!]); }} newer={() => setCursors((current) => current.slice(0, -1))} hasNewer={cursors.length > 0}/>} {tab === "launch" && <LaunchSetup distributor={contract?.address ?? null} account={wallet.account}/>} {tab === "admin" && <Administration key={`${contract?.address ?? "none"}:${wallet.account ?? "disconnected"}`} snapshot={snapshot.data} wallet={wallet} refresh={refresh}/>}<div className="rewards-workspace-footer"><span><ShieldCheck size={12}/>Amounts come from the configured contract and published holder snapshots.</span>{contract ? <AddressLink address={contract.address} label="View distributor"/> : <button className="rewards-text-button" onClick={() => setTab("launch")}>Review launch setup <ArrowRight size={12}/></button>}</div></div>;
}
